def transform(grid):
    """Intersect the two masks separated by a full-height divider; mark overlaps 2."""
    h, w = len(grid), len(grid[0])
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0:
            left_w, right_w = c, w - c - 1
            if left_w == right_w:
                return [[2 if grid[r][j] != 0 and grid[r][c + 1 + j] != 0 else 0
                         for j in range(left_w)] for r in range(h)]
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != 0:
            top_h, bottom_h = r, h - r - 1
            if top_h == bottom_h:
                return [[2 if grid[i][c] != 0 and grid[r + 1 + i][c] != 0 else 0
                         for c in range(w)] for i in range(top_h)]
    raise ValueError("no centered uniform divider with equal-sized panels")
